export function setLanguage(code){locale=Object.hasOwn(LANGUAGES,code)?code:'en';return locale;}
export const getLanguage=()=>locale;
export function copy(section){return LANGUAGES[locale].content[section]??EN[section];}
export function t(key,values={}){const value=copy('ui')[key]??EN.ui[key]??key;return value.replace(/\{(\w+)\}/g,(_,k)=>String(values[k]??''));}

