export function tr(key,values=[]){const parts=LANGUAGES[locale].content.legacy?.[key]??LEGACY[key];if(Array.isArray(parts))return parts.reduce((s,p,i)=>s+p+(i<values.length?values[i]:''),'');return parts??key;}

export function localizeStatic(root=document){
 const map=new Map(Object.entries(LEGACY).filter(([,v])=>typeof v==='string').map(([key,value])=>[value,key]));
 const walker=document.createTreeWalker(root.body??root,NodeFilter.SHOW_TEXT);let node;
 while(node=walker.nextNode()){if(['SCRIPT','STYLE'].includes(node.parentElement?.tagName))continue;const key=map.get(node.textContent);if(key)node.textContent=tr(key);}
 for(const el of root.querySelectorAll('[aria-label],[title],[placeholder],[alt]'))for(const attr of ['aria-label','title','placeholder','alt']){const key=map.get(el.getAttribute(attr));if(key)el.setAttribute(attr,tr(key));}
}

