EN.facts.marsStorm={title:EN.ui.marsStormTitle,text:'On 20 May 2024, a storm hit Mars. Beside Curiosity, a crew member would have had about as much radiation as 30 chest X-rays. NASA said it was not deadly. It was the biggest surge RAD had seen since landing, as reported in June 2024. MAVEN saw auroras across the whole planet. Cliffs or lava tubes could give extra shelter. This was a different event from our flare record.',url:'https://www.nasa.gov/solar-system/planets/mars/nasa-watches-mars-light-up-during-epic-solar-storm/'};
EN.facts.delay.text=EN.ui.delayFact;
EN.facts.dust.text='Dust blocked light on InSight’s panels. With less light, the lander made less electricity.';
EN.facts.water.text='The space station showed how to reuse 98 out of 100 parts of its water. Crews clean and reuse water so they can go farther.';
for(const card of Object.values(EN.cards))for(const choice of card.choices){choice.hint=choice.hint.replace(/Power/g,'Battery').replace(/battery cell \(8 points\)/g,'Battery −8').replace(/panels −15% clear/g,'more panel dust');choice.outcome=choice.outcome.replace(/stored power cell/g,'8 Battery points').replace(/little power/g,'little Battery');}
EN.cards.dustdevil.choices.find(c=>c.id==='risk').hint=EN.ui.devilRisk;
EN.cards.filter.choices.find(c=>c.id==='shake').hint=EN.ui.filterRisk;
EN.cards.storm.choices.find(c=>c.id==='shelter').hint='Get inside now. The wall helps protect us.';
