Object.assign(EN.sites.arcadia,{story:'This wide plain has signs of ice just under the ground.',fact:'NASA made a map of ice in parts of this plain. A future crew might use it for water.'});
const shortFacts={
 rad:'Curiosity has a tool called RAD. It measures radiation on Mars. These readings help us plan walls for future crews.',
 plants:'Veggie is a small garden on the space station. NASA tests how plants grow there. Crews can eat some fresh food too.',
 oxygen:'MOXIE was a test on Mars. It made oxygen, the gas we breathe, from the thin Mars air. A full air system would need more parts.',
 chapea:'CHAPEA crews live in a Mars-like home on Earth for a year. They test how to stay well and work as a team with few supplies.',
 hera:'HERA crews live and work in a small home on Earth. Their tests can last up to 45 days. This helps us plan for long trips.',
 landing:'After spaceflight, crews can feel wobbly. NASA tests how they walk and work. A harness can help copy the pull of Mars gravity.',
 nbl:'Crews train for spacewalks in a huge pool. It is called the Neutral Buoyancy Lab. They learn each task and how to help each other.',
 geology:'Crews learn to read maps and pick up rock samples on Earth. Trips to rocky places like Iceland help them learn what to look for.',
 walls:'NASA has studied walls filled with water. Water can help block radiation, the energy that can pass through things. It can do more than one job.',
 mars:'Rust in the rocks helps make Mars red. Mars also has old river valleys and lake beds.',
 filters:'Dust can clog air vents on the space station. NASA tests ways to keep them clean. Our shake-clean choice is a made-up shortcut.',
 cold:'Mars is cold. Its average is about −60 °C. Real crews would need thick walls and a good way to heat their home.',
 cargo:'Cargo ships bring supplies to the space station. We packed our Mars crates months ago. They did not come from Earth in a flash.',
 ice:'NASA maps ice below the ground on Mars. A crew might use it one day. They would need tools to find and clean it.',
 meteorite:'Opportunity found an iron space rock on Mars. A space rock on the ground is called a meteorite. Our panel card is made up.',
 art:'NASA shares art made by crews in space. Kids can make their own space art too. In our story, the crew gets drawings in a message.'
};
for(const [id,text] of Object.entries(shortFacts))EN.facts[id].text=text;

