Object.assign(EN.facts,{
  "roverPlans": {
    "text": "NASA rover drivers plan each day's moves ahead of time and test them in a simulator before sending. Perseverance can also drive part of the way by itself with AutoNav.",
    "url": "https://www.nasa.gov/podcasts/on-a-mission/how-to-drive-a-mars-rover-s4e8/"
  },
  "autoNav": {
    "text": "People choose Perseverance’s stops. AutoNav helps it map the ground and find a safe path around nearby rocks.",
    "url": "https://science.nasa.gov/resource/how-perseverance-drives-on-mars/"
  },
  "streambed": {
    "text": "Curiosity found old stream rocks in Gale Crater. Their pebbles were up to golf-ball size. Water had rounded them over a long time. The stream was ankle to hip deep and moved at least about walking pace.",
    "url": "https://www.jpl.nasa.gov/news/pebbly-rocks-testify-to-old-streambed-on-mars/"
  },
  "jezeroLayers": {
    "text": "Jezero once had a lake and a river delta. A delta is a fan of sand and mud left where a river meets a lake. Its rock layers hold clues to that past.",
    "url": "https://www.jpl.nasa.gov/news/nasas-perseverance-sheds-more-light-on-jezero-craters-watery-past/"
  },
  "lavaHoles": {
    "text": "Spirit found lava rocks with holes made by gas bubbles. Holes can also form in other ways, so a hole alone is not proof of lava.",
    "url": "https://science.nasa.gov/resource/gusev-lava-rocks/"
  },
  "marsSalt": {
    "text": "Water can leave salt behind when it dries up. A white crust alone does not prove salt. Our clue is made simple for the game.",
    "url": "https://www.jpl.nasa.gov/images/pia17875-looking-for-salts-on-mars/"
  },
  "marsMeteorite": {
    "text": "Curiosity found a metal meteorite on Mars. A meteorite is a space rock that reaches the ground. A laser tool helped check what it was made of. Shine alone is not proof.",
    "url": "https://science.nasa.gov/resource/curiosity-rover-finds-and-examines-a-meteorite-on-mars-2/"
  },
  "rockContext": {
    "text": "A rock can have holes for more than one reason. Teams study the whole site and use tools to test their ideas.",
    "url": "https://science.nasa.gov/photojournal/puzzling-point-lake-outcrop-revisited/"
  }
});
